const schools = [
  "CEI LUIZ FELIPE", "CEM SAO CRISTOVAO", "CEI ARCO IRIS", "CEI BRUNO LEONARDO", "CEI DOM FRANCO",
  "CEI MENINO JESUS", "CEI NOSSO LAR", "CEI VASCO PAPA", "CEI CRIANÇA FELIZ", "CEM GUILHERME",
  "CEM ORLANDO PEREIRA", "EM MARIA HILDA", "EM PAULO FREIRE", "EM JOSE ANCHIETA", "ERM ALVARES AZEVEDO",
  "ERM CORA CORALINA", "ERM EUCLIDES CUNHA", "ERM OSVALDO CRUZ", "ERM VINICIUS DE MORAIS"
];

const navAdmin = [
  { label: "Visão geral", icon: LayoutDashboard, key: "dashboard" },
  { label: "Escolas", icon: Building2, key: "schools" },
  { label: "Usuários", icon: UserCog, key: "users" },
  { label: "Alunos", icon: GraduationCap, key: "students" },
  { label: "Importar PDF", icon: FileUp, key: "import" },
  { label: "Faltas", icon: ClipboardList, key: "absences" },
  { label: "Envios", icon: FileCheck2, key: "submissions" },
  { label: "Relatórios", icon: BarChart3, key: "reports" },
];

const navSchool = [
  { label: "Minha escola", icon: LayoutDashboard, key: "dashboard" },
  { label: "Alunos", icon: GraduationCap, key: "students" },
  { label: "Registrar faltas", icon: ClipboardList, key: "absences" },
  { label: "Meus envios", icon: FileCheck2, key: "submissions" },
];

function StatCard({ title, value, caption, icon: Icon, tone = "blue" }: { title: string; value: string; caption: string; icon: typeof Users; tone?: string }) {
  return <Card className="stat-card border-0 shadow-sm">
    <CardContent className="p-5">
      <div className="flex items-start justify-between gap-4">
        <div><p className="text-sm text-muted-foreground">{title}</p><p className="mt-2 text-3xl font-semibold tracking-tight">{value}</p><p className="mt-2 text-xs text-muted-foreground">{caption}</p></div>
        <div className={`icon-tile tone-${tone}`}><Icon className="h-5 w-5" /></div>
      </div>
    </CardContent>
  </Card>;
}

function EmptyState({ title, description, action }: { title: string; description: string; action?: React.ReactNode }) {
  return <div className="empty-state"><div className="empty-icon"><BookOpen className="h-6 w-6" /></div><h3>{title}</h3><p>{description}</p>{action}</div>;
}

export default function Home() {
  const { user, loading, logout } = useAuth();
  const [, setLocation] = useLocation();
  const [active, setActive] = useState("dashboard");
  const [mobileOpen, setMobileOpen] = useState(false);
  const [schoolFilter, setSchoolFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [importOpen, setImportOpen] = useState(false);
  const overviewQuery = trpc.dashboard.overview.useQuery(undefined, { enabled: !!user });
  const studentsQuery = trpc.students.list.useQuery(undefined, { enabled: !!user });
  const schoolsQuery = trpc.schools.list.useQuery(undefined, { enabled: !!user && user.role === "admin" });
  const usersQuery = trpc.users.list.useQuery(undefined, { enabled: !!user && user.role === "admin" });
  const absencesQuery = trpc.absences.list.useQuery(undefined, { enabled: !!user });
  const [studentOpen, setStudentOpen] = useState(false);
  const isAdmin = user?.role === "admin";
  const nav = isAdmin ? navAdmin : navSchool;
  const displayName = user?.name || (isAdmin ? "Administrador" : "Equipe escolar");
  const initials = displayName.split(" ").map(part => part[0]).slice(0, 2).join("").toUpperCase();
  const filteredSchools = useMemo(() => schools.filter(s => s.toLowerCase().includes(query.toLowerCase())), [query]);

  if (loading) return <div className="loading-screen"><div className="brand-mark small"><ShieldCheck /></div><span>Carregando ambiente seguro...</span></div>;
  if (!user) return <Landing />;

  const title = nav.find(item => item.key === active)?.label || "Visão geral";
  return <div className="app-frame">
    <aside className="desktop-sidebar">
      <div className="brand-lockup"><div className="brand-mark"><ShieldCheck className="h-5 w-5" /></div><div><p className="brand-name">EduControl</p><p className="brand-subtitle">Gestão educacional</p></div></div>
      <div className="workspace-label">{isAdmin ? "ADMINISTRAÇÃO CENTRAL" : "UNIDADE ESCOLAR"}</div>
      <nav className="sidebar-nav">{nav.map(item => <button key={item.key} className={`sidebar-link ${active === item.key ? "active" : ""}`} onClick={() => setActive(item.key)}><item.icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{active === item.key && <span className="active-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><Bell className="h-4 w-4" /></div><p>Precisa de ajuda?</p><span>Fale com a secretaria</span></div><button className="sidebar-link" onClick={logout}><LogOut className="h-[18px] w-[18px]" /><span>Sair da conta</span></button></div>
    </aside>
    <Sheet open={mobileOpen} onOpenChange={setMobileOpen}><SheetContent side="left" className="mobile-sidebar"><SheetHeader><SheetTitle><div className="brand-lockup"><div className="brand-mark"><ShieldCheck className="h-5 w-5" /></div><div><p className="brand-name">EduControl</p><p className="brand-subtitle">Gestão educacional</p></div></div></SheetTitle></SheetHeader><nav className="sidebar-nav mt-8">{nav.map(item => <button key={item.key} className={`sidebar-link ${active === item.key ? "active" : ""}`} onClick={() => { setActive(item.key); setMobileOpen(false); }}><item.icon className="h-[18px] w-[18px]" /><span>{item.label}</span></button>)}</nav></SheetContent></Sheet>
    <main className="main-content">
      <header className="topbar"><div className="flex items-center gap-3"><Button variant="ghost" size="icon" className="mobile-menu" onClick={() => setMobileOpen(true)}><Menu /></Button><div><p className="eyebrow">{isAdmin ? "SECRETARIA MUNICIPAL DE EDUCAÇÃO" : "PAINEL DA UNIDADE"}</p><h1>{title}</h1></div></div><div className="topbar-actions"><button className="notification-button"><Bell className="h-[18px] w-[18px]" /><span /></button><div className="profile"><Avatar className="h-9 w-9"><AvatarFallback>{initials}</AvatarFallback></Avatar><div className="hidden sm:block"><p className="profile-name">{displayName}</p><p className="profile-role">{isAdmin ? "Administrador" : "Usuário escola"}</p></div><ChevronDown className="hidden sm:block h-4 w-4 text-muted-foreground" /></div></div></header>
      <div className="content-wrap">
        {active === "dashboard" && <Dashboard isAdmin={isAdmin} displayName={displayName} onImport={() => setImportOpen(true)} overview={overviewQuery.data} /> }
        {active === "schools" && <SchoolSection schools={schoolsQuery.data ?? []} loading={schoolsQuery.isLoading} />}
        {active === "import" && <ImportPanel onOpen={() => setImportOpen(true)} />}
        {active === "students" && <StudentsSection isAdmin={isAdmin} students={studentsQuery.data ?? []} loading={studentsQuery.isLoading} onImport={() => setActive("import")} />}
        {(active === "absences" || active === "submissions" || active === "users" || active === "reports") && <GenericSection active={active} isAdmin={isAdmin} onImport={() => setImportOpen(true)} users={usersQuery.data ?? []} absences={absencesQuery.data ?? []} schools={schoolsQuery.data ?? []} />}
      </div>
    </main>
    <ImportDialog open={importOpen} onOpenChange={setImportOpen} existingStudents={studentsQuery.data ?? []} schools={schoolsQuery.data ?? []} />
    <Dialog open={studentOpen} onOpenChange={setStudentOpen}><DialogContent><DialogHeader><DialogTitle>Dados do aluno</DialogTitle></DialogHeader><EmptyState title="Selecione um aluno" description="Escolha um cadastro na lista para consultar seus dados completos." /></DialogContent></Dialog>
  </div>;
}

function Landing() { return <div className="landing"><div className="landing-orbit orbit-one" /><div className="landing-orbit orbit-two" /><div className="landing-card"><div className="brand-mark large"><ShieldCheck /></div><p className="eyebrow">SECRETARIA MUNICIPAL DE EDUCAÇÃO</p><h1>Gestão escolar com<br /><em>clareza e cuidado.</em></h1><p className="landing-copy">Alunos, faltas e envios em um só lugar.</p><Button className="primary-button landing-button" onClick={() => startLogin()}>Acessar plataforma <ArrowUpRight className="h-4 w-4" /></Button><div className="landing-trust"><CheckCircle2 className="h-4 w-4" /> Ambiente seguro e com acesso controlado</div></div><div className="landing-side"><div className="side-stat"><span>19</span><p>unidades escolares<br />conectadas</p></div><div className="side-line" /><div className="side-quote">“Organizar a rotina é abrir espaço para cuidar melhor do que realmente importa.”</div></div></div>; }

function Dashboard({ isAdmin, displayName, onImport, overview }: { isAdmin: boolean; displayName: string; onImport: () => void; overview?: { schools: number; students: number; absences: number; ficai?: number; pending: number } }) { return <><section className="dashboard-hero"><div className="hero-copy"><p className="eyebrow">{isAdmin ? "CENTRAL DE OPERAÇÕES" : "ACOMPANHAMENTO DA UNIDADE"}</p><h2>Olá, {displayName.split(" ")[0]} <span>•</span></h2><p className="hero-description">Acompanhe alunos, faltas e envios em um só lugar.</p><div className="hero-meta"><span><CheckCircle2 className="h-4 w-4" /> Ambiente atualizado</span><span><ShieldCheck className="h-4 w-4" /> Dados protegidos</span></div></div><div className="hero-action"><div className="hero-orbit" /><div className="hero-action-icon"><BarChart3 /></div><div><p className="eyebrow">{isAdmin ? "GESTÃO CENTRALIZADA" : "ROTINA ESCOLAR"}</p><strong>{isAdmin ? "A rede em um só lugar" : "Sua unidade em foco"}</strong><span>Indicadores e pendências em um só lugar.</span></div>{isAdmin && <Button className="primary-button" onClick={onImport}><UploadCloud className="h-4 w-4" /> Importar PDF</Button>}</div></section><div className="stats-grid"><StatCard title="Escolas ativas" value={overview ? String(overview.schools) : "—"} caption={isAdmin ? "Toda a rede municipal" : "Unidade vinculada"} icon={Building2} tone="blue" /><StatCard title="Alunos cadastrados" value={overview ? String(overview.students) : "—"} caption="Cadastro ativo" icon={Users} tone="violet" /><StatCard title="Faltas registradas" value={overview ? String(overview.absences) : "—"} caption="No período atual" icon={ClipboardList} tone="amber" /><StatCard title="FICAI" value={overview ? String(overview.ficai ?? 0) : "—"} caption="Participação registrada" icon={ShieldCheck} tone="green" /><StatCard title="Envios pendentes" value={overview ? String(overview.pending) : "—"} caption="Aguardando análise" icon={Clock3} tone="green" /></div><div className="dashboard-grid"><Card className="chart-card"><CardHeader className="card-heading"><div><p className="eyebrow">ACOMPANHAMENTO</p><CardTitle>Movimentação de faltas</CardTitle><p className="card-subtitle">Uma leitura rápida do ritmo de registros no período.</p></div><Select defaultValue="month"><SelectTrigger className="compact-select"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="month">Este mês</SelectItem><SelectItem value="quarter">Último trimestre</SelectItem></SelectContent></Select></CardHeader><CardContent><div className="chart-placeholder modern-chart"><div className="chart-grid-lines" /><div className="chart-bars"><i style={{ height: "32%" }} /><i style={{ height: "48%" }} /><i style={{ height: "38%" }} /><i style={{ height: "64%" }} /><i style={{ height: "55%" }} /><i style={{ height: "82%" }} /><i style={{ height: "68%" }} /><i style={{ height: "92%" }} /></div><div className="chart-axis"><span>sem 1</span><span>sem 2</span><span>sem 3</span><span>sem 4</span></div><div className="chart-message"><div className="chart-live-dot" /><span>Pronto para receber seus primeiros registros</span></div></div></CardContent></Card><Card className="quick-card"><CardHeader className="card-heading"><div><p className="eyebrow">ATENÇÃO</p><CardTitle>Próximas ações</CardTitle><p className="card-subtitle">Atalhos para manter a rotina em dia.</p></div><Settings2 className="h-5 w-5 text-muted-foreground" /></CardHeader><CardContent className="quick-actions"><button onClick={onImport}><div className="quick-icon blue"><FileUp /></div><div><strong>Importar alunos</strong><span>Adicionar via PDF</span></div><ArrowUpRight /></button><button><div className="quick-icon amber"><ClipboardList /></div><div><strong>Registrar falta</strong><span>Adicionar ocorrência</span></div><ArrowUpRight /></button><button><div className="quick-icon green"><FileCheck2 /></div><div><strong>Ver envios</strong><span>Acompanhar status</span></div><ArrowUpRight /></button></CardContent></Card></div><Card className="activity-card"><CardHeader className="card-heading"><div><p className="eyebrow">TIMELINE</p><CardTitle>Atividade recente</CardTitle><p className="card-subtitle">Últimas movimentações no sistema.</p></div><Button variant="ghost" size="sm">Ver tudo <ArrowUpRight className="ml-1 h-3.5 w-3.5" /></Button></CardHeader><CardContent><EmptyState title="Nenhuma atividade registrada" description="Assim que houver importações ou envios, eles aparecerão nesta linha do tempo." /></CardContent></Card></>; }

function SectionHeader({ title, description, action, children }: { title: string; description: string; action?: React.ReactNode; children: React.ReactNode }) { return <div className="section-stack"><div className="section-heading"><div><p className="eyebrow">GESTÃO</p><h2>{title}</h2><p className="muted-copy">{description}</p></div>{action}</div>{children}</div>; }

function SchoolSection({ schools: rows, loading }: { schools: Array<{ id: number; nome: string; codigo: string; ativo: number; alunos: number }>; loading: boolean }) { const [query, setQuery] = useState(""); const [open, setOpen] = useState(false); const [nome, setNome] = useState(""); const [codigo, setCodigo] = useState(""); const [editing, setEditing] = useState<typeof rows[number] | null>(null); const utils = trpc.useUtils(); const create = trpc.schools.create.useMutation({ onSuccess: () => { toast.success("Escola cadastrada."); setOpen(false); setNome(""); setCodigo(""); utils.schools.list.invalidate(); }, onError: error => toast.error(error.message) }); const update = trpc.schools.update.useMutation({ onSuccess: () => { toast.success("Escola atualizada."); setEditing(null); setOpen(false); utils.schools.list.invalidate(); }, onError: error => toast.error(error.message) }); const filtered = rows.filter(row => row.nome.toLowerCase().includes(query.toLowerCase()) || row.codigo.toLowerCase().includes(query.toLowerCase())); return <SectionHeader title="Escolas cadastradas" description="Gerencie as unidades atendidas pela secretaria." action={<Button className="primary-button" onClick={() => setOpen(true)}><Building2 className="h-4 w-4" /> Nova escola</Button>}><Card className="table-card"><div className="table-toolbar"><div className="search-box"><Search className="h-4 w-4" /><Input placeholder="Buscar escola..." value={query} onChange={e => setQuery(e.target.value)} /></div><Button variant="outline" className="filter-button"><Filter className="h-4 w-4" /> Filtros</Button></div><div className="responsive-table"><table><thead><tr><th>Unidade escolar</th><th>Código</th><th>Alunos</th><th>Status</th><th /></tr></thead><tbody>{loading ? <tr><td colSpan={5}>Carregando escolas...</td></tr> : filtered.map(row => <tr key={row.id}><td><div className="table-primary"><div className="table-avatar">{row.nome.slice(0, 2)}</div><span>{row.nome}</span></div></td><td>{row.codigo}</td><td>{row.alunos}</td><td><Badge className={`status-badge ${row.ativo ? "success" : "warning"}`}><span />{row.ativo ? "Ativa" : "Inativa"}</Badge></td><td className="action-buttons"><Button variant="ghost" size="sm" onClick={() => { setEditing(row); setNome(row.nome); setCodigo(row.codigo); setOpen(true); }}>Editar</Button><Button variant="ghost" size="sm" onClick={() => update.mutate({ id: row.id, nome: row.nome, codigo: row.codigo, ativo: row.ativo ? 0 : 1 })}>{row.ativo ? "Desativar" : "Ativar"}</Button></td></tr>)}</tbody></table></div></Card><Dialog open={open} onOpenChange={value => { setOpen(value); if (!value) { setEditing(null); setNome(""); setCodigo(""); } }}><DialogContent><DialogHeader><DialogTitle>{editing ? "Editar escola" : "Nova escola"}</DialogTitle></DialogHeader><div className="form-grid"><label className="wide">Nome<input value={nome} onChange={event => setNome(event.target.value)} placeholder="Nome da unidade" /></label><label>Código<input value={codigo} onChange={event => setCodigo(event.target.value)} placeholder="ESC-20" /></label></div><div className="dialog-footer"><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button className="primary-button" disabled={!nome || !codigo || create.isPending || update.isPending} onClick={() => editing ? update.mutate({ id: editing.id, nome, codigo, ativo: editing.ativo }) : create.mutate({ nome, codigo })}>{create.isPending || update.isPending ? "Salvando..." : editing ? "Salvar alterações" : "Cadastrar escola"}</Button></div></DialogContent></Dialog></SectionHeader>; }

function ImportPanel({ onOpen }: { onOpen: () => void }) { return <SectionHeader title="Importar alunos" description="Leia o relatório escolar e revise os dados antes de salvar."><Card className="import-card"><div className="import-dropzone"><div className="upload-visual"><FileUp className="h-7 w-7" /></div><h3>Importe um relatório em PDF</h3><p>O sistema identifica a escola e separa cada aluno por bloco, sem misturar informações.</p><Button className="primary-button" onClick={onOpen}><UploadCloud className="h-4 w-4" /> Selecionar PDF</Button><span className="file-note">PDF até 25 MB · leitura de todas as páginas</span></div><div className="import-steps"><div><span>01</span><div><strong>Leitura segura</strong><p>Extração por campos e blocos independentes.</p></div></div><div><span>02</span><div><strong>Pré-visualização</strong><p>Valide alertas, duplicidades e dados ausentes.</p></div></div><div><span>03</span><div><strong>Confirmação explícita</strong><p>Nada é gravado antes da sua aprovação.</p></div></div></div></Card></SectionHeader>; }

function ImportDialog({ open, onOpenChange, existingStudents, schools: schoolRows }: { open: boolean; onOpenChange: (open: boolean) => void; existingStudents: Array<{ matricula: string; inep: string | null; escolaId: number }>; schools: Array<{ id: number; nome: string }> }) { const [file, setFile] = useState<File | null>(null); const [reading, setReading] = useState(false); const [progress, setProgress] = useState(0); const [preview, setPreview] = useState<ParsedStudent[]>([]); const [school, setSchool] = useState(""); const [error, setError] = useState(""); const utils = trpc.useUtils(); const confirm = trpc.imports.confirm.useMutation({ onSuccess: result => { toast.success(`${result.inserted} alunos importados; ${result.skipped} registros ignorados.`); utils.students.list.invalidate(); utils.dashboard.overview.invalidate(); close(); }, onError: mutationError => setError(mutationError.message) }); const readFile = async () => { if (!file) return; setReading(true); setError(""); try { const raw = await extractPdfText(file, (page, total) => setProgress(Math.round((page / total) * 100))); const parsed = parseImportText(raw); setSchool(parsed.escola); const schoolRow = schoolRows.find(row => row.nome.toLowerCase() === parsed.escola.toLowerCase()); setPreview(markDuplicateStudents(parsed.alunos, existingStudents.filter(student => student.escolaId === schoolRow?.id))); } catch { setError("Não foi possível ler este PDF. Confirme se o arquivo contém texto selecionável."); } finally { setReading(false); } }; const close = () => { setFile(null); setPreview([]); setSchool(""); setProgress(0); setError(""); onOpenChange(false); }; return <Dialog open={open} onOpenChange={openState => openState ? onOpenChange(true) : close()}><DialogContent className="import-dialog"><DialogHeader><DialogTitle>{preview.length ? "Conferir importação" : "Importar alunos por PDF"}</DialogTitle><p className="dialog-description">{preview.length ? `${preview.length} blocos encontrados · ${school || "Escola não identificada"}. Nada foi gravado ainda.` : "Selecione o arquivo para iniciar a leitura. A gravação só acontecerá após a conferência."}</p></DialogHeader>{!preview.length && <label className="file-picker"><input type="file" accept="application/pdf" onChange={e => setFile(e.target.files?.[0] || null)} /><FileUp className="h-6 w-6" /><strong>{file ? file.name : "Clique para selecionar o PDF"}</strong><span>{file ? `${(file.size / 1024 / 1024).toFixed(2)} MB selecionado` : "ou arraste o arquivo até aqui"}</span></label>}{reading && <div className="validation-note"><Clock3 className="h-4 w-4" /><span>Lendo PDF... {progress}% das páginas processadas.</span></div>}{error && <div className="validation-note text-destructive"><AlertCircle className="h-4 w-4" /><span>{error}</span></div>}{preview.length > 0 && <div className="preview-table"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Responsável</th><th>Situação</th></tr></thead><tbody>{preview.slice(0, 8).map((student, index) => <tr key={`${student.nome}-${index}`}><td>{student.nome || "—"}</td><td>{student.turma || "—"}</td><td>{student.responsavel || "—"}</td><td><Badge className={`status-badge ${student.status === "OK" ? "success" : student.status === "ATENCAO" ? "warning" : "error"}`}>{student.duplicate ? "DUPLICADO" : student.status}</Badge></td></tr>)}</tbody></table></div>}{file && !preview.length && <div className="validation-note"><CheckCircle2 className="h-4 w-4" /><span>Arquivo pronto para leitura e pré-visualização.</span></div>}<div className="dialog-footer"><Button variant="outline" onClick={close}>Cancelar</Button>{preview.length ? <Button className="primary-button" disabled={!school || confirm.isPending} onClick={() => confirm.mutate({ escola: school, students: preview })}>{confirm.isPending ? "Gravando..." : "Confirmar importação"}</Button> : <Button className="primary-button" disabled={!file || reading} onClick={readFile}>{reading ? "Lendo..." : "Ler e pré-visualizar"}</Button>}</div></DialogContent></Dialog>; }

function StudentsSection({ isAdmin, students, loading, onImport }: { isAdmin: boolean; students: Array<{ id: number; nome: string; turma: string; matricula: string; inep: string | null; dataMatricula: string | null; responsavel: string | null; fone1: string | null; fone2: string | null; endereco: string | null; escolaId: number }>; loading: boolean; onImport: () => void }) { const [query, setQuery] = useState(""); const [turma, setTurma] = useState("all"); const [selected, setSelected] = useState<typeof students[number] | null>(null); const [absenceOpen, setAbsenceOpen] = useState(false); const [date, setDate] = useState(""); const [days, setDays] = useState("1"); const [reason, setReason] = useState(""); const [note, setNote] = useState(""); const [ficai, setFicai] = useState<"SIM" | "NAO">("NAO"); const absence = trpc.absences.create.useMutation({ onSuccess: () => { toast.success("Falta salva como rascunho."); setAbsenceOpen(false); setDate(""); setReason(""); setNote(""); setFicai("NAO"); }, onError: error => toast.error(error.message) }); const turmas = Array.from(new Set(students.map(student => student.turma))).sort(); const filtered = students.filter(student => student.nome.toLowerCase().includes(query.toLowerCase()) && (turma === "all" || student.turma === turma)); const grouped = filtered.reduce<Record<string, typeof students>>((acc, student) => { (acc[student.turma] ||= []).push(student); return acc; }, {}); const absenceInput = useMemo(() => selected ? { alunoId: selected.id } : undefined, [selected?.id]); const studentAbsences = trpc.absences.list.useQuery(absenceInput, { enabled: !!selected }); return <SectionHeader title={isAdmin ? "Alunos" : "Alunos da unidade"} description="Consulte os cadastros organizados por turma."><div className="filter-row"><div className="search-box flex-1"><Search className="h-4 w-4" /><Input placeholder="Buscar aluno..." value={query} onChange={e => setQuery(e.target.value)} /></div><Select value={turma} onValueChange={setTurma}><SelectTrigger className="filter-select"><SelectValue placeholder="Todas as turmas" /></SelectTrigger><SelectContent><SelectItem value="all">Todas as turmas</SelectItem>{turmas.map(item => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select>{isAdmin && <Button className="primary-button" onClick={onImport}><UploadCloud className="h-4 w-4" /> Importar</Button>}</div><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Aluno</th><th>Matrícula</th><th>Turma</th><th>Responsável</th><th /></tr></thead><tbody>{loading ? <tr><td colSpan={5}>Carregando cadastros...</td></tr> : Object.entries(grouped).length ? Object.entries(grouped).flatMap(([group, rows]) => [<tr key={`group-${group}`} className="group-row"><td colSpan={5}><strong>{group}</strong><span>{rows.length} aluno{rows.length === 1 ? "" : "s"}</span></td></tr>, ...rows.map(student => <tr key={student.id}><td><button className="table-primary" onClick={() => setSelected(student)}><div className="table-avatar">{student.nome.slice(0, 2)}</div><span>{student.nome}</span></button></td><td>{student.matricula}</td><td>{student.turma}</td><td>{student.responsavel || "—"}</td><td><Button variant="ghost" size="sm" onClick={() => { setSelected(student); setAbsenceOpen(true); }}>Registrar falta</Button></td></tr>)]) : [<tr key="empty"><td colSpan={5}><EmptyState title="Nenhum aluno encontrado" description="Importe e confirme um PDF para começar o acompanhamento." action={isAdmin ? <Button className="primary-button" onClick={onImport}><UploadCloud className="h-4 w-4" /> Importar alunos</Button> : undefined} /></td></tr>]}</tbody></table></div></Card><Dialog open={!!selected && !absenceOpen} onOpenChange={open => !open && setSelected(null)}><DialogContent><DialogHeader><DialogTitle>{selected?.nome}</DialogTitle></DialogHeader>{selected && <div className="student-details"><div><span>Turma</span><strong>{selected.turma}</strong></div><div><span>Matrícula</span><strong>{selected.matricula}</strong></div><div><span>INEP</span><strong>{selected.inep || "Não informado"}</strong></div><div><span>Responsável</span><strong>{selected.responsavel || "Não informado"}</strong></div><div><span>Telefone 1</span><strong>{selected.fone1 || "Não informado"}</strong></div><div><span>Telefone 2</span><strong>{selected.fone2 || "Não informado"}</strong></div><div className="wide"><span>Endereço</span><strong>{selected.endereco || "Não informado"}</strong></div><div className="wide absence-history"><div className="history-heading"><span>Histórico de faltas</span><small>{studentAbsences.isLoading ? "Carregando..." : `${studentAbsences.data?.length ?? 0} registro(s)`}</small></div>{studentAbsences.data?.length ? <div className="history-list">{studentAbsences.data.map(item => <div className="history-item" key={item.id}><div><strong>{item.dataFalta}</strong><span>{item.quantidadeDias} dia(s) · {item.motivo}</span></div><div className="history-meta"><Badge className={`status-badge ${item.ficaiParticipa === "SIM" ? "warning" : "success"}`}>FICAI: {item.ficaiParticipa}</Badge><small>{item.status}</small></div>{item.observacao && <p>{item.observacao}</p>}</div>)}</div> : <p className="history-empty">Nenhuma falta registrada para este aluno.</p>}</div><Button className="primary-button wide" onClick={() => setAbsenceOpen(true)}><ClipboardList className="h-4 w-4" /> Marcar falta</Button><StudentEditButton student={selected} /></div>}</DialogContent></Dialog><Dialog open={absenceOpen} onOpenChange={setAbsenceOpen}><DialogContent><DialogHeader><DialogTitle>Registrar falta</DialogTitle><p className="dialog-description">{selected?.nome} · {selected?.turma}</p></DialogHeader><div className="form-grid"><label>Data<input type="date" value={date} onChange={event => setDate(event.target.value)} /></label><label>Dias<input type="number" min="1" value={days} onChange={event => setDays(event.target.value)} /></label><label className="wide">Motivo<input value={reason} onChange={event => setReason(event.target.value)} placeholder="Ex.: Doença" /></label><label className="wide">Observação<textarea value={note} onChange={event => setNote(event.target.value)} placeholder="Detalhes opcionais" /></label><label className="wide">Participa da ficha FICAI<select value={ficai} onChange={event => setFicai(event.target.value as "SIM" | "NAO")}><option value="NAO">Não participa</option><option value="SIM">Sim, participa</option></select></label></div><div className="dialog-footer"><Button variant="outline" onClick={() => setAbsenceOpen(false)}>Cancelar</Button><Button className="primary-button" disabled={!selected || !date || !reason || absence.isPending} onClick={() => selected && absence.mutate({ alunoId: selected.id, escolaId: selected.escolaId, dataFalta: date, quantidadeDias: Number(days), motivo: reason, observacao: note || undefined, ficaiParticipa: ficai })}>{absence.isPending ? "Salvando..." : "Salvar rascunho"}</Button></div></DialogContent></Dialog></SectionHeader>; }

function StudentEditButton({ student }: { student: { id: number; nome: string; turma: string; responsavel: string | null; fone1: string | null; fone2: string | null; endereco: string | null; escolaId: number } }) { const [open, setOpen] = useState(false); const [nome, setNome] = useState(student.nome); const [turma, setTurma] = useState(student.turma); const [responsavel, setResponsavel] = useState(student.responsavel || ""); const [fone1, setFone1] = useState(student.fone1 || ""); const [fone2, setFone2] = useState(student.fone2 || ""); const [endereco, setEndereco] = useState(student.endereco || ""); const utils = trpc.useUtils(); const update = trpc.students.update.useMutation({ onSuccess: () => { toast.success("Cadastro do aluno atualizado."); setOpen(false); utils.students.list.invalidate(); }, onError: error => toast.error(error.message) }); return <><Button variant="outline" className="wide" onClick={() => setOpen(true)}>Editar cadastro</Button><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Editar cadastro do aluno</DialogTitle></DialogHeader><div className="form-grid"><label className="wide">Nome<input value={nome} onChange={event => setNome(event.target.value)} /></label><label>Turma<input value={turma} onChange={event => setTurma(event.target.value)} /></label><label>Responsável<input value={responsavel} onChange={event => setResponsavel(event.target.value)} /></label><label>Telefone 1<input value={fone1} onChange={event => setFone1(event.target.value)} /></label><label>Telefone 2<input value={fone2} onChange={event => setFone2(event.target.value)} /></label><label className="wide">Endereço<textarea value={endereco} onChange={event => setEndereco(event.target.value)} /></label></div><div className="dialog-footer"><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button className="primary-button" disabled={!nome || !turma || update.isPending} onClick={() => update.mutate({ id: student.id, nome, turma, responsavel: responsavel || undefined, fone1: fone1 || undefined, fone2: fone2 || undefined, endereco: endereco || undefined, escolaId: student.escolaId })}>{update.isPending ? "Salvando..." : "Salvar alterações"}</Button></div></DialogContent></Dialog></>; }

function SubmissionSection() { const utils = trpc.useUtils(); const query = trpc.submissions.list.useQuery(); const absences = trpc.absences.list.useQuery(); const [periodo, setPeriodo] = useState(""); const [observacao, setObservacao] = useState(""); const [reviewOpen, setReviewOpen] = useState(false); const mutation = trpc.submissions.create.useMutation({ onSuccess: () => { toast.success("Registros enviados ao administrador."); setPeriodo(""); setObservacao(""); utils.submissions.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: error => toast.error(error.message) }); return <SectionHeader title="Meus envios" description="Envie os registros do período para revisão da secretaria."><Card className="submission-compose"><div><p className="eyebrow">NOVO ENVIO</p><h3>Enviar registros de faltas</h3><p className="card-subtitle">A ação cria um envio com status ENVIADO para a unidade vinculada.</p></div><div className="form-grid"><label>Período<input value={periodo} onChange={event => setPeriodo(event.target.value)} placeholder="Ex.: Agosto de 2026" /></label><label className="wide">Observação<textarea value={observacao} onChange={event => setObservacao(event.target.value)} placeholder="Mensagem opcional ao administrador" /></label></div><div className="compose-actions"><Button className="primary-button" disabled={!periodo || mutation.isPending} onClick={() => setReviewOpen(true)}><FileCheck2 className="h-4 w-4" /> Revisar e enviar</Button></div></Card><Dialog open={reviewOpen} onOpenChange={setReviewOpen}><DialogContent><DialogHeader><DialogTitle>Revisar faltas antes do envio</DialogTitle><p className="dialog-description">Confirme os registros da unidade e a participação na FICAI. Nada será enviado antes da confirmação.</p></DialogHeader><div className="review-summary"><strong>{absences.data?.length ?? 0} falta(s)</strong><span>serão vinculadas ao período {periodo || "informado"}</span></div><div className="history-list review-list">{absences.isLoading ? <p className="history-empty">Carregando faltas...</p> : absences.data?.length ? absences.data.map(item => <div className="history-item" key={item.id}><div><strong>{item.aluno || "Aluno"} · {item.dataFalta}</strong><span>{item.quantidadeDias} dia(s) · {item.motivo}</span></div><Badge className={`status-badge ${item.ficaiParticipa === "SIM" ? "warning" : "success"}`}>FICAI: {item.ficaiParticipa}</Badge></div>) : <p className="history-empty">Nenhuma falta registrada para enviar.</p>}</div><div className="dialog-footer"><Button variant="outline" onClick={() => setReviewOpen(false)}>Voltar</Button><Button className="primary-button" disabled={!periodo || !absences.data?.length || mutation.isPending} onClick={() => { mutation.mutate({ periodo, observacao: observacao || undefined }); setReviewOpen(false); }}>{mutation.isPending ? "Enviando..." : "Confirmar envio"}</Button></div></DialogContent></Dialog><Card className="table-card"><div className="card-heading"><div><CardTitle>Histórico de envios</CardTitle><p className="card-subtitle">Acompanhe o status de cada período.</p></div></div><div className="responsive-table"><table><thead><tr><th>Período</th><th>Escola</th><th>Enviado em</th><th>Status</th></tr></thead><tbody>{query.isLoading ? <tr><td colSpan={4}>Carregando envios...</td></tr> : query.data?.length ? query.data.map(item => <tr key={item.id}><td className="table-primary">{item.periodo}</td><td>{item.escola || "Unidade vinculada"}</td><td>{item.enviadoEm ? new Date(item.enviadoEm).toLocaleDateString("pt-BR") : "—"}</td><td><Badge className="status-badge success"><span />{item.status}</Badge></td></tr>) : <tr><td colSpan={4}><EmptyState title="Nenhum envio encontrado" description="Os períodos enviados aparecerão nesta lista." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function AdminSubmissionsSection() { const utils = trpc.useUtils(); const query = trpc.submissions.list.useQuery(); const [note, setNote] = useState(""); const review = trpc.submissions.review.useMutation({ onSuccess: () => { toast.success("Envio atualizado."); utils.submissions.list.invalidate(); utils.dashboard.overview.invalidate(); }, onError: error => toast.error(error.message) }); return <SectionHeader title="Envios recebidos" description="Revise os registros enviados pelas unidades escolares."><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Escola</th><th>Período</th><th>Data de envio</th><th>Status</th><th>Observação</th><th>Ações</th></tr></thead><tbody>{query.isLoading ? <tr><td colSpan={6}>Carregando envios...</td></tr> : query.data?.length ? query.data.map(item => <tr key={item.id}><td className="table-primary">{item.escola || "—"}</td><td>{item.periodo}</td><td>{item.enviadoEm ? new Date(item.enviadoEm).toLocaleDateString("pt-BR") : "—"}</td><td><Badge className="status-badge success"><span />{item.status}</Badge></td><td>{item.observacaoAdmin || item.observacao || "—"}</td><td className="action-buttons"><Input aria-label={`Observação do envio ${item.periodo}`} value={note} onChange={event => setNote(event.target.value)} placeholder="Observação" /><Button variant="outline" size="sm" onClick={() => review.mutate({ id: item.id, status: "EM_ANALISE", observacaoAdmin: note || undefined })}>Em análise</Button><Button size="sm" className="primary-button" onClick={() => review.mutate({ id: item.id, status: "APROVADO", observacaoAdmin: note || undefined })}>Aprovar</Button><Button variant="ghost" size="sm" onClick={() => review.mutate({ id: item.id, status: "REJEITADO", observacaoAdmin: note || undefined })}>Rejeitar</Button></td></tr>) : <tr><td colSpan={6}><EmptyState title="Nenhum envio encontrado" description="Os envios das escolas aparecerão nesta lista." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function AdminUsersSection({ users }: { users: Array<{ id: number; nome: string; email: string; perfil: "ADMIN" | "ESCOLA"; escola: string | null; ativo: number }> }) { return <SectionHeader title="Usuários do sistema" description="Acompanhe perfis, acessos e vínculos por unidade." action={<Button className="primary-button"><UserCog className="h-4 w-4" /> Novo usuário</Button>}><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Escola vinculada</th><th>Status</th></tr></thead><tbody>{users.length ? users.map(item => <tr key={item.id}><td className="table-primary">{item.nome}</td><td>{item.email}</td><td><Badge variant="outline">{item.perfil}</Badge></td><td>{item.escola || "Acesso central"}</td><td><Badge className={`status-badge ${item.ativo ? "success" : "warning"}`}><span />{item.ativo ? "Ativo" : "Inativo"}</Badge></td></tr>) : <tr><td colSpan={5}><EmptyState title="Nenhum usuário operacional" description="Crie o vínculo após o usuário concluir o acesso autenticado." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function AdminAbsencesSection({ absences }: { absences: Array<{ id: number; aluno: string | null; turma: string | null; dataFalta: string; quantidadeDias: number; motivo: string; status: string }> }) { const [search, setSearch] = useState(""); const filtered = absences.filter(item => (item.aluno || "").toLowerCase().includes(search.toLowerCase())); return <SectionHeader title="Registro de faltas" description="Consulte ocorrências por aluno, turma, período e status."><div className="filter-row"><div className="search-box flex-1"><Search className="h-4 w-4" /><Input placeholder="Buscar aluno..." value={search} onChange={event => setSearch(event.target.value)} /></div><Button variant="outline" className="filter-button"><CalendarDays className="h-4 w-4" /> Período</Button><Select defaultValue="all"><SelectTrigger className="filter-select"><SelectValue placeholder="Todos os status" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os status</SelectItem><SelectItem value="RASCUNHO">RASCUNHO</SelectItem><SelectItem value="ENVIADO">ENVIADO</SelectItem><SelectItem value="APROVADO">APROVADO</SelectItem></SelectContent></Select></div><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Data</th><th>Dias</th><th>Motivo</th><th>Status</th></tr></thead><tbody>{filtered.length ? filtered.map(item => <tr key={item.id}><td className="table-primary">{item.aluno || "—"}</td><td>{item.turma || "—"}</td><td>{item.dataFalta}</td><td>{item.quantidadeDias}</td><td>{item.motivo}</td><td><Badge className="status-badge success"><span />{item.status}</Badge></td></tr>) : <tr><td colSpan={6}><EmptyState title="Nenhuma falta registrada" description="As ocorrências aparecerão aqui conforme forem cadastradas." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function AdminUsersManager({ users, schools: schoolRows }: { users: Array<{ id: number; nome: string; email: string; perfil: "ADMIN" | "ESCOLA"; escola: string | null; ativo: number }>; schools: Array<{ id: number; nome: string; codigo: string; ativo: number; alunos: number }> }) { const [open, setOpen] = useState(false); const [authUserId, setAuthUserId] = useState(""); const [nome, setNome] = useState(""); const [email, setEmail] = useState(""); const [perfil, setPerfil] = useState<"ADMIN" | "ESCOLA">("ESCOLA"); const [escolaId, setEscolaId] = useState(""); const utils = trpc.useUtils(); const create = trpc.users.create.useMutation({ onSuccess: () => { toast.success("Usuário operacional criado."); setOpen(false); setAuthUserId(""); setNome(""); setEmail(""); setEscolaId(""); utils.users.list.invalidate(); }, onError: error => toast.error(error.message) }); return <SectionHeader title="Usuários do sistema" description="Acompanhe perfis, acessos e vínculos por unidade." action={<Button className="primary-button" onClick={() => setOpen(true)}><UserCog className="h-4 w-4" /> Novo usuário</Button>}><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Usuário</th><th>E-mail</th><th>Perfil</th><th>Escola vinculada</th><th>Status</th></tr></thead><tbody>{users.length ? users.map(item => <tr key={item.id}><td className="table-primary">{item.nome}</td><td>{item.email}</td><td><Badge variant="outline">{item.perfil}</Badge></td><td>{item.escola || "Acesso central"}</td><td><Badge className={`status-badge ${item.ativo ? "success" : "warning"}`}><span />{item.ativo ? "Ativo" : "Inativo"}</Badge></td></tr>) : <tr><td colSpan={5}><EmptyState title="Nenhum usuário operacional" description="Crie o vínculo após o usuário concluir o acesso autenticado." /></td></tr>}</tbody></table></div></Card><Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Novo usuário operacional</DialogTitle><p className="dialog-description">Para ESCOLA, o nome de usuário será automaticamente o nome da unidade selecionada. O authUserId deve corresponder ao usuário OAuth existente.</p></DialogHeader><div className="form-grid"><label>Auth user ID<input type="number" min="1" value={authUserId} onChange={event => setAuthUserId(event.target.value)} /></label><label>Perfil<select value={perfil} onChange={event => setPerfil(event.target.value as "ADMIN" | "ESCOLA")}><option value="ESCOLA">ESCOLA</option><option value="ADMIN">ADMIN</option></select></label><label className="wide">Nome de usuário{perfil === "ESCOLA" ? <input value={schoolRows.find(row => String(row.id) === escolaId)?.nome || "Selecione a escola"} readOnly /> : <input value={nome} onChange={event => setNome(event.target.value)} placeholder="Nome do administrador" />}</label><label className="wide">E-mail<input type="email" value={email} onChange={event => setEmail(event.target.value)} /></label>{perfil === "ESCOLA" && <label className="wide">Unidade escolar<select value={escolaId} onChange={event => setEscolaId(event.target.value)}><option value="">Selecione uma unidade</option>{schoolRows.map(row => <option key={row.id} value={row.id}>{row.nome}</option>)}</select></label>}</div><div className="dialog-footer"><Button variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button className="primary-button" disabled={!authUserId || !(perfil === "ESCOLA" ? escolaId : nome) || !email || (perfil === "ESCOLA" && !escolaId) || create.isPending} onClick={() => create.mutate({ authUserId: Number(authUserId), nome: perfil === "ESCOLA" ? (schoolRows.find(row => String(row.id) === escolaId)?.nome || nome) : nome, email, perfil, escolaId: perfil === "ESCOLA" ? Number(escolaId) : undefined })}>{create.isPending ? "Salvando..." : "Criar usuário"}</Button></div></DialogContent></Dialog></SectionHeader>; }

function AdminAbsencesManager() { const [search, setSearch] = useState(""); const [period, setPeriod] = useState(""); const [ficai, setFicai] = useState<"all" | "SIM" | "NAO">("all"); const [status, setStatus] = useState<"all" | "RASCUNHO" | "ENVIADO" | "EM_ANALISE" | "APROVADO" | "REJEITADO">("all"); const query = trpc.absences.list.useQuery({ search: search || undefined, period: period || undefined, ficaiParticipa: ficai === "all" ? undefined : ficai, status: status === "all" ? undefined : status }); return <SectionHeader title="Registro de faltas" description="Consulte ocorrências por aluno, turma, período e status."><div className="filter-row"><div className="search-box flex-1"><Search className="h-4 w-4" /><Input aria-label="Buscar aluno nas faltas" placeholder="Buscar aluno..." value={search} onChange={event => setSearch(event.target.value)} /></div><div className="search-box"><CalendarDays className="h-4 w-4" /><Input aria-label="Filtrar faltas por período" placeholder="2026-08" value={period} onChange={event => setPeriod(event.target.value)} /></div><Select value={ficai} onValueChange={value => setFicai(value as typeof ficai)}><SelectTrigger className="filter-select" aria-label="Filtrar faltas por FICAI"><SelectValue placeholder="Todos FICAI" /></SelectTrigger><SelectContent><SelectItem value="all">Todos FICAI</SelectItem><SelectItem value="SIM">FICAI: Sim</SelectItem><SelectItem value="NAO">FICAI: Não</SelectItem></SelectContent></Select><Select value={status} onValueChange={value => setStatus(value as typeof status)}><SelectTrigger className="filter-select" aria-label="Filtrar faltas por status"><SelectValue placeholder="Todos os status" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os status</SelectItem><SelectItem value="RASCUNHO">RASCUNHO</SelectItem><SelectItem value="ENVIADO">ENVIADO</SelectItem><SelectItem value="EM_ANALISE">EM_ANALISE</SelectItem><SelectItem value="APROVADO">APROVADO</SelectItem><SelectItem value="REJEITADO">REJEITADO</SelectItem></SelectContent></Select></div><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Data</th><th>Dias</th><th>Motivo</th><th>FICAI</th><th>Status</th></tr></thead><tbody>{query.isLoading ? <tr><td colSpan={7}>Carregando faltas...</td></tr> : query.data?.length ? query.data.map(item => <tr key={item.id}><td className="table-primary">{item.aluno || "—"}</td><td>{item.turma || "—"}</td><td>{item.dataFalta}</td><td>{item.quantidadeDias}</td><td>{item.motivo}</td><td><Badge className={`status-badge ${item.ficaiParticipa === "SIM" ? "warning" : "success"}`}>FICAI: {item.ficaiParticipa}</Badge></td><td><Badge className="status-badge success"><span />{item.status}</Badge></td></tr>) : <tr><td colSpan={7}><EmptyState title="Nenhuma falta encontrada" description="Ajuste os filtros ou aguarde novos registros." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function AdminReportsSection() { const overview = trpc.dashboard.overview.useQuery(); const absences = trpc.absences.list.useQuery(); return <SectionHeader title="Relatórios" description="Visão consolidada para apoiar a tomada de decisão." action={<Button className="primary-button" onClick={() => toast.success("Relatório pronto para consulta.")}><BarChart3 className="h-4 w-4" /> Gerar relatório</Button>}><div className="stats-grid report-stats"><StatCard title="Escolas ativas" value={String(overview.data?.schools ?? "—")} caption="Rede municipal" icon={Building2} tone="blue" /><StatCard title="Alunos" value={String(overview.data?.students ?? "—")} caption="Cadastros ativos" icon={Users} tone="violet" /><StatCard title="Faltas" value={String(overview.data?.absences ?? "—")} caption="Registros consolidados" icon={ClipboardList} tone="amber" /><StatCard title="Envios analisados" value={String(overview.data?.analyzed ?? "—")} caption="Aprovados ou rejeitados" icon={FileCheck2} tone="green" /></div><Card className="table-card"><div className="card-heading"><div><CardTitle>Recorte atual</CardTitle><p className="card-subtitle">Últimos registros encontrados para auditoria.</p></div></div><div className="responsive-table"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Data</th><th>Dias</th><th>Motivo</th><th>Status</th></tr></thead><tbody>{absences.data?.slice(0, 10).map(item => <tr key={item.id}><td className="table-primary">{item.aluno || "—"}</td><td>{item.turma || "—"}</td><td>{item.dataFalta}</td><td>{item.quantidadeDias}</td><td>{item.motivo}</td><td>{item.status}</td></tr>)}</tbody></table></div></Card></SectionHeader>; }

function AdminReportsManager({ schools: schoolRows }: { schools: Array<{ id: number; nome: string; codigo: string; ativo: number; alunos: number }> }) { const [schoolId, setSchoolId] = useState("all"); const [turma, setTurma] = useState(""); const [period, setPeriod] = useState(""); const [search, setSearch] = useState(""); const [ficai, setFicai] = useState<"all" | "SIM" | "NAO">("all"); const [status, setStatus] = useState<"all" | "RASCUNHO" | "ENVIADO" | "EM_ANALISE" | "APROVADO" | "REJEITADO">("all"); const overview = trpc.dashboard.overview.useQuery(); const query = trpc.absences.list.useQuery({ escolaId: schoolId === "all" ? undefined : Number(schoolId), turma: turma || undefined, period: period || undefined, search: search || undefined, ficaiParticipa: ficai === "all" ? undefined : ficai, status: status === "all" ? undefined : status }); return <SectionHeader title="Relatórios" description="Visão consolidada com filtros operacionais para a secretaria." action={<Button className="primary-button" onClick={() => toast.success("Relatório atualizado com os filtros selecionados.")}><BarChart3 className="h-4 w-4" /> Atualizar relatório</Button>}><div className="report-filters"><Select value={schoolId} onValueChange={setSchoolId}><SelectTrigger aria-label="Filtrar relatório por escola"><SelectValue placeholder="Todas as escolas" /></SelectTrigger><SelectContent><SelectItem value="all">Todas as escolas</SelectItem>{schoolRows.map(row => <SelectItem key={row.id} value={String(row.id)}>{row.nome}</SelectItem>)}</SelectContent></Select><Input aria-label="Filtrar relatório por turma" placeholder="Turma" value={turma} onChange={event => setTurma(event.target.value)} /><Input aria-label="Filtrar relatório por período" placeholder="Período (2026-08)" value={period} onChange={event => setPeriod(event.target.value)} /><Input aria-label="Filtrar relatório por aluno" placeholder="Aluno" value={search} onChange={event => setSearch(event.target.value)} /><Select value={ficai} onValueChange={value => setFicai(value as typeof ficai)}><SelectTrigger aria-label="Filtrar relatório por FICAI"><SelectValue placeholder="Todos FICAI" /></SelectTrigger><SelectContent><SelectItem value="all">Todos FICAI</SelectItem><SelectItem value="SIM">FICAI: Sim</SelectItem><SelectItem value="NAO">FICAI: Não</SelectItem></SelectContent></Select><Select value={status} onValueChange={value => setStatus(value as typeof status)}><SelectTrigger aria-label="Filtrar relatório por status"><SelectValue placeholder="Todos os status" /></SelectTrigger><SelectContent><SelectItem value="all">Todos os status</SelectItem><SelectItem value="RASCUNHO">RASCUNHO</SelectItem><SelectItem value="ENVIADO">ENVIADO</SelectItem><SelectItem value="EM_ANALISE">EM_ANALISE</SelectItem><SelectItem value="APROVADO">APROVADO</SelectItem><SelectItem value="REJEITADO">REJEITADO</SelectItem></SelectContent></Select></div><div className="stats-grid report-stats"><StatCard title="Escolas ativas" value={String(overview.data?.schools ?? "—")} caption="Rede municipal" icon={Building2} tone="blue" /><StatCard title="Alunos" value={String(overview.data?.students ?? "—")} caption="Cadastros ativos" icon={Users} tone="violet" /><StatCard title="Faltas filtradas" value={String(query.data?.length ?? "—")} caption="Resultado atual" icon={ClipboardList} tone="amber" /><StatCard title="Participam da FICAI" value={String(query.data?.filter(item => item.ficaiParticipa === "SIM").length ?? "—")} caption="No recorte atual" icon={ShieldCheck} tone="green" /><StatCard title="Envios analisados" value={String(overview.data?.analyzed ?? "—")} caption="Aprovados ou rejeitados" icon={FileCheck2} tone="green" /></div><Card className="table-card"><div className="responsive-table"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Data</th><th>Dias</th><th>Motivo</th><th>FICAI</th><th>Status</th></tr></thead><tbody>{query.isLoading ? <tr><td colSpan={7}>Carregando relatório...</td></tr> : query.data?.length ? query.data.map(item => <tr key={item.id}><td className="table-primary">{item.aluno || "—"}</td><td>{item.turma || "—"}</td><td>{item.dataFalta}</td><td>{item.quantidadeDias}</td><td>{item.motivo}</td><td><Badge className={`status-badge ${item.ficaiParticipa === "SIM" ? "warning" : "success"}`}>{item.ficaiParticipa}</Badge></td><td>{item.status}</td></tr>) : <tr><td colSpan={7}><EmptyState title="Nenhum dado para os filtros" description="Ajuste escola, turma, período, aluno ou status." /></td></tr>}</tbody></table></div></Card></SectionHeader>; }

function GenericSection({ active, isAdmin, onImport, users, absences, schools: schoolRows }: { active: string; isAdmin: boolean; onImport: () => void; users: Array<{ id: number; nome: string; email: string; perfil: "ADMIN" | "ESCOLA"; escola: string | null; ativo: number }>; absences: Array<{ id: number; aluno: string | null; turma: string | null; dataFalta: string; quantidadeDias: number; motivo: string; status: string }>; schools: Array<{ id: number; nome: string; codigo: string; ativo: number; alunos: number }> }) { if (active === "submissions" && !isAdmin) return <SubmissionSection />; if (active === "submissions" && isAdmin) return <AdminSubmissionsSection />; if (active === "users" && isAdmin) return <AdminUsersManager users={users} schools={schoolRows} />; if (active === "absences" && isAdmin) return <AdminAbsencesManager />; if (active === "reports" && isAdmin) return <AdminReportsManager schools={schoolRows} />; const map: Record<string, [string, string, string]> = { absences: ["Registro de faltas", "Consulte e acompanhe as ocorrências registradas por aluno.", "Nenhuma falta registrada"], submissions: ["Envios recebidos", "Acompanhe o fluxo de revisão dos registros enviados.", "Nenhum envio encontrado"], users: ["Usuários do sistema", "Gerencie perfis, acessos e vínculos por unidade.", "Nenhum usuário cadastrado"], reports: ["Relatórios", "Gere visões consolidadas para apoiar a tomada de decisão.", "Nenhum dado disponível"] }; const [title, description, empty] = map[active]; return <SectionHeader title={title} description={description} action={active === "reports" ? <Button className="primary-button"><BarChart3 className="h-4 w-4" /> Gerar relatório</Button> : undefined}><div className="filter-row"><div className="search-box flex-1"><Search className="h-4 w-4" /><Input placeholder="Buscar..." /></div><Select defaultValue="all"><SelectTrigger className="filter-select"><SelectValue placeholder="Todas as escolas" /></SelectTrigger><SelectContent><SelectItem value="all">Todas as escolas</SelectItem>{schools.slice(0, 5).map(s => <SelectItem key={s} value={s}>{s}</SelectItem>)}</SelectContent></Select><Button variant="outline" className="filter-button"><CalendarDays className="h-4 w-4" /> Período</Button></div><Card><EmptyState title={empty} description="Os dados serão exibidos aqui assim que houver movimentações no sistema." action={active === "absences" && !isAdmin ? <Button className="primary-button" onClick={onImport}><ClipboardList className="h-4 w-4" /> Registrar falta</Button> : undefined} /></Card></SectionHeader>; }
